// ----- core/assets.js
// 아이콘·이미지 에셋 로더.
// 빌드 시 assets.generated.js 에 data URI 맵이 채워져 dist/lxp.js 하나로 자립 동작합니다.
// 소스(ESM)로 직접 쓸 때 맵이 비어 있으면 assets/ 폴더의 상대경로를 사용합니다.


let BASE = 'src/assets/';
/** ESM 직접 사용 시 에셋 폴더 경로 지정 */
function setAssetBase(path) { BASE = path.endsWith('/') ? path : path + '/'; }

/** 에셋 URL. name 은 파일명(확장자 제외). 예: 'tab-home', 'avatar-02' */
function asset(name) {
  if (ASSETS[name]) return ASSETS[name];
  const isImg = /^(avatar|thumb)-/.test(name);
  return BASE + (isImg ? 'images/' : 'icons/') + name + (/^thumb-|^avatar-0/.test(name) ? '.png' : '.svg');
}

/** 등록된 아이콘 이름 목록 (빌드 결과 기준) */
function iconNames() {
  return Object.keys(ASSETS).filter((k) => !/^(avatar|thumb)-/.test(k));
}

/**
 * 아이콘. Figma 원본 SVG를 그대로 사용합니다(색 포함).
 * color 를 주면 CSS mask 로 단색 틴트 (아이디에이션용).
 */
function Icon(name, { size = 24, color, className = '', label = '' } = {}) {
  const src = asset(name);
  if (color) {
    return `<span class="${cx('lxp-icon', 'lxp-icon--tint', className)}" role="${label ? 'img' : 'presentation'}"${label ? ` aria-label="${esc(label)}"` : ' aria-hidden="true"'} style="width:${size}px;height:${size}px;--lxp-icon-src:url('${src}');color:${color}"></span>`;
  }
  return `<img class="${cx('lxp-icon', className)}" src="${src}" width="${size}" height="${size}" alt="${esc(label)}"${label ? '' : ' aria-hidden="true"'}>`;
}

// ----- components/button.js
// 버튼: Button(btn-base-state) · IconButton(btn-icon-base-state)


/**
 * 텍스트 버튼
 * @param {string} p.label
 * @param {'primary'|'secondary'|'outline'|'gray'|'ghost'} [p.variant]
 *   primary  : 코스모스 블루 (저장하기/대화시작하기)
 *   secondary: 연회색 배경 (내 강의실 편집)
 *   outline  : 흰 배경 + 보더 (차단 해제 · 리스트 내)
 *   gray     : 진회색 배경 (차단 해제 · 푸터)
 * @param {'lg'|'md'|'xs'} [p.size] lg=44, md=40, xs=28
 * @param {string} [p.icon] 왼쪽 아이콘 이름
 * @param {boolean} [p.block] 가로 100%
 * @param {boolean} [p.disabled]
 */
function Button({ label = '', variant = 'primary', size = 'lg', icon, block = false, disabled = false, className = '' } = {}) {
  const iconSize = size === 'xs' ? 12 : 16;
  return `<button class="${cx('lxp-btn', `lxp-btn--${variant}`, `lxp-btn--${size}`, block && 'lxp-btn--block', icon && 'has-icon', className)}"${disabled ? ' disabled' : ''}>
    ${icon ? Icon(icon, { size: iconSize }) : ''}<span>${esc(label)}</span>
  </button>`;
}

/**
 * 아이콘 버튼
 * @param {string} p.icon
 * @param {24|36|40} [p.size] 버튼 크기 (아이콘: 14/18/20)
 * @param {boolean} [p.active] 선택 상태 (연회색 배경)
 * @param {boolean} [p.round] 원형 + 연회색 배경 (메시지 입력 +/↑)
 */
function IconButton({ icon, size = 36, active = false, round = false, label = '', className = '' } = {}) {
  const iconSize = { 24: 14, 36: 18, 40: 20 }[size] || 18;
  return `<button class="${cx('lxp-icon-btn', `lxp-icon-btn--${size}`, active && 'is-active', round && 'lxp-icon-btn--round', className)}" aria-label="${esc(label || icon)}">
    ${Icon(icon, { size: iconSize })}
  </button>`;
}

// ----- components/display.js
// 데이터 표시: Chip · Badge · Avatar · AvatarGroup · Tag · Toast



/**
 * 칩 (chip/times — "3시간 남았어요", "D-3")
 * @param {'info'|'neutral'|'posi'|'nega'|'warn'} [p.tone]
 */
function Chip({ label = '', tone = 'info', className = '' } = {}) {
  return `<span class="${cx('lxp-chip', `lxp-chip--${tone}`, className)}">${esc(label)}</span>`;
}

/**
 * 카운트 배지 (새 메시지 수 — 민트 배경)
 * @param {'md'|'sm'|'square'} [p.size] md=22px/12SB, sm=18px/11SB, square=radius4/13M
 */
function Badge({ count = 1, size = 'md', className = '' } = {}) {
  return `<span class="${cx('lxp-badge', `lxp-badge--${size}`, className)}">${esc(count)}</span>`;
}

/**
 * 아바타 (Avata-base: 24/28/32/36/40/48)
 * @param {string} [p.src] 이미지 URL 또는 에셋명 (avatar-02~05). 없으면 이름 첫 글자 플레이스홀더
 * @param {string} [p.name] 플레이스홀더 이니셜용
 * @param {boolean} [p.dimmed] 차단/나간 사용자 (투명도 25%)
 */
function Avatar({ src, name = '', size = 48, dimmed = false, alt = '', className = '' } = {}) {
  const box = `width:${size}px;height:${size}px`;
  if (!src) {
    return `<span class="${cx('lxp-avatar', 'is-empty', dimmed && 'is-dimmed', className)}" style="${box};font-size:${Math.round(size * 0.4)}px" aria-label="${esc(alt || name)}">${esc(name.slice(0, 1))}</span>`;
  }
  const url = /^avatar-/.test(src) ? asset(src) : src;
  return `<span class="${cx('lxp-avatar', dimmed && 'is-dimmed', className)}" style="${box}">
    <img src="${url}" alt="${esc(alt)}">
  </span>`;
}

/** 그룹 아바타 (아바타 + "+N" 원형, 겹침 -24px) */
function AvatarGroup({ src = 'avatar-03', more = 5, size = 48 } = {}) {
  return `<span class="lxp-avatar-group" style="--size:${size}px">
    ${Avatar({ src, size })}<span class="lxp-avatar-group__more">+${esc(more)}</span>
  </span>`;
}

/**
 * 선택 태그 (con-base — 받는 사람 선택 칩)
 * @param {'md'|'lg'} [p.size] md=40, lg=44
 * @param {string|false} [p.avatar] 아바타 에셋/URL. false 면 아이콘형
 * @param {boolean} [p.closable]
 */
function Tag({ label = 'label', size = 'md', avatar = 'avatar-03', icon = 'plus', closable = true } = {}) {
  const av = avatar ? Avatar({ src: avatar, size: size === 'lg' ? 40 : 36 }) : Icon(icon, { size: 18 });
  return `<span class="${cx('lxp-tag', `lxp-tag--${size}`, avatar ? 'has-avatar' : 'has-icon')}">
    ${av}<span>${esc(label)}</span>${closable ? IconButton({ icon: 'x-close-14', size: 24, label: '삭제' }) : ''}
  </span>`;
}

/** 토스트 (Notice_guide_secondary — "저장되었습니다") */
function Toast({ label = '저장되었습니다', icon = 'check' } = {}) {
  return `<div class="lxp-toast" role="status">${icon ? Icon(icon, { size: 16 }) : ''}<span>${esc(label)}</span></div>`;
}

// ----- components/navigation.js
// 상단/하단 내비게이션: StatusBar · Header · AppHeader · TabBar · Dropdown
// Figma: 공통(24:12502) — iPhone header / Header / App_header / Tab bar



/** iOS 상태바 (Figma 24:13152) */
function StatusBar({ className = '' } = {}) {
  return `<div class="${cx('lxp-statusbar', className)}" aria-hidden="true">
    <img class="lxp-statusbar__left" src="${asset('statusbar-left')}" alt="">
    <img class="lxp-statusbar__right" src="${asset('statusbar-right')}" alt="">
  </div>`;
}

/** 드롭다운 메뉴 (Header message-open 의 more-dropdown, 79:18854) */
function Dropdown({ items = [], className = '', style = '' } = {}) {
  return `<div class="${cx('lxp-dropdown', className)}" role="menu" style="${style}">
    ${items.map((it) => `<button class="lxp-dropdown__item" role="menuitem">
      ${it.icon ? Icon(it.icon, { size: 18 }) : ''}<span>${esc(it.label)}</span></button>`).join('')}
  </div>`;
}

const HEADER_PRESETS = {
  home: { title: '홈', actions: [{ icon: 'bell-18', size: 36 }] },
  class: { title: '2026년 1학기', caret: true, actions: [{ icon: 'grid-active', active: true }, { icon: 'list-inactive' }] },
  class_list: { title: '2026년 1학기', caret: true, actions: [{ icon: 'grid-inactive' }, { icon: 'list-active', active: true }] },
  message: { title: '메시지', actions: [{ icon: 'search-20', size: 40 }, { icon: 'dots-vertical-20', size: 40 }] },
  'message-open': {
    title: '메시지',
    actions: [{ icon: 'search-20', size: 40 }, { icon: 'dots-vertical-20', size: 40 }],
    menu: [{ icon: 'message-chat-circle', label: '차단 대화 관리' }],
  },
  more: { title: '더보기', actions: [] },
};

/**
 * 메인 탭 헤더 (h68, Head/20B)
 * @param {object} p
 * @param {'home'|'class'|'class_list'|'message'|'message-open'|'more'} [p.variant]
 * @param {string} [p.title] @param {boolean} [p.caret] 학기 선택 ▼
 * @param {{icon:string,size?:36|40,active?:boolean,label?:string}[]} [p.actions]
 * @param {{icon?:string,label:string}[]} [p.menu] 열린 드롭다운
 */
function Header(p = {}) {
  const preset = HEADER_PRESETS[p.variant || 'home'] || {};
  const { title, caret, actions = [], menu } = { ...preset, ...p };
  return `<header class="lxp-header">
    <div class="lxp-header__title">
      <h1>${esc(title)}</h1>${caret ? Icon('caret-down', { size: 20 }) : ''}
    </div>
    <div class="lxp-header__actions">
      ${actions.map((a) => IconButton({ icon: a.icon, size: a.size || 36, active: a.active, label: a.label })).join('')}
    </div>
    ${menu ? Dropdown({ items: menu, className: 'lxp-header__menu' }) : ''}
  </header>`;
}

/**
 * 서브 페이지 헤더 (h56, 하단 보더)
 * @param {'default'|'popup_pull'|'page'|'page_chat'|'photo-viewer'} [p.type]
 * @param {string} [p.title] @param {string} [p.subtitle] photo-viewer 날짜
 */
function AppHeader({ type = 'page', title = '', subtitle = '', right } = {}) {
  const leftIcon = { default: 'menu', popup_pull: 'x-close' }[type] || 'chevron-left';
  const rightIcon = right !== undefined ? right
    : type === 'default' ? 'bell-18'
    : (type === 'page_chat' || type === 'photo-viewer') ? 'dots-vertical' : null;
  const center = type === 'default' ? '<div class="lxp-app-header__title"></div>'
    : `<div class="lxp-app-header__title"><p class="lxp-ellipsis">${esc(title)}</p>${subtitle ? `<span>${esc(subtitle)}</span>` : ''}</div>`;
  return `<header class="lxp-app-header">
    ${IconButton({ icon: leftIcon, size: 36, label: leftIcon === 'chevron-left' ? '뒤로' : leftIcon === 'menu' ? '메뉴' : '닫기' })}
    ${center}
    ${rightIcon ? IconButton({ icon: rightIcon, size: 36 }) : '<span class="lxp-icon-btn lxp-icon-btn--36" aria-hidden="true"></span>'}
  </header>`;
}

const TABS = [
  { key: 'home', label: '홈', icon: 'tab-home', activeIcon: 'tab-home-active' },
  { key: 'class', label: '내강의실', icon: 'tab-class', activeIcon: 'tab-class-active' },
  { key: 'message', label: '메시지', icon: 'tab-message', activeIcon: 'tab-message-active' },
  { key: 'more', label: '더보기', icon: 'tab-more', activeIcon: 'tab-more-active' },
];

/**
 * 하단 탭바 (h82)
 * @param {'home'|'class'|'message'|'more'} [p.active]
 * @param {Record<string, number|string>} [p.badges] 예: { message: 11 }
 * @param {string[]} [p.newDots] 예: ['more']
 * @param {typeof TABS} [p.items] 커스텀 탭
 */
function TabBar({ active = 'home', badges = { message: 11 }, newDots = [], items = TABS } = {}) {
  return `<nav class="lxp-tabbar">
    ${items.map((t) => {
      const on = t.key === active;
      return `<a class="${cx('lxp-tabbar__item', on && 'is-active')}" ${on ? 'aria-current="page"' : ''}>
        ${Icon(on ? t.activeIcon : t.icon, { size: 24 })}
        <span>${esc(t.label)}</span>
        ${badges[t.key] != null ? `<i class="lxp-tabbar__badge">${esc(badges[t.key])}</i>` : ''}
        ${newDots.includes(t.key) ? `<img class="lxp-tabbar__dot" src="${asset('dot-new')}" alt="새 소식">` : ''}
      </a>`;
    }).join('')}
  </nav>`;
}

const TAB_ITEMS = TABS;

// ----- components/input.js
// 입력: Input(input-base-state 86:18467) · MessageInput · Footer(37:14876)



/**
 * 검색/텍스트 입력 (h44, radius 12)
 * @param {'enabled'|'focused'|'disabled'} [p.state] focused 는 정적 시안용(실제 포커스 시 자동 적용)
 * @param {'normal'|'filled'|'invalid'} [p.validation]
 * @param {string} [p.value] @param {string} [p.placeholder]
 * @param {string} [p.icon] 리딩 아이콘 (기본 search)
 */
function Input({ state = 'enabled', validation, value = '', placeholder = '검색어를 입력하세요.', icon = 'search', className = '' } = {}) {
  const v = validation || (value ? 'filled' : 'normal');
  const disabled = state === 'disabled';
  const lead = disabled && v !== 'invalid' ? 'help-circle' : disabled ? 'search-disabled' : icon;
  return `<label class="${cx('lxp-input', `is-${state}`, `is-${v}`, className)}">
    ${Icon(lead, { size: 16, className: cx('lxp-input__lead', disabled && v === 'invalid' && 'is-faded') })}
    <input type="text" value="${esc(value)}" placeholder="${esc(placeholder)}"${disabled ? ' disabled' : ''}>
    ${v === 'filled' ? `<button class="lxp-input__clear" aria-label="지우기">${Icon('x-circle-filled', { size: 16 })}</button>` : ''}
  </label>`;
}

/** 메시지 입력 필드 (pill) — Footer 'message input' 내부 */
function MessageInput({ placeholder = '메세지를 입력하세요.', value = '' } = {}) {
  return `<div class="lxp-msg-input">
    ${IconButton({ icon: 'plus', size: 36, round: true, label: '첨부' })}
    <input type="text" value="${esc(value)}" placeholder="${esc(placeholder)}">
    ${IconButton({ icon: 'arrow-up', size: 36, round: true, label: '보내기' })}
  </div>`;
}

/**
 * 하단 고정 영역
 * @param {'empty'|'button'|'count-button'|'message-input'|'message-block'} [p.type]
 * @param {string} [p.label] 버튼 라벨
 * @param {number} [p.count] count-button 의 인원 수
 * @param {string} [p.caption] message-block 안내 문구
 */
function Footer({ type = 'button', label, count = 2, caption = '차단 친구와는 대화할 수 없습니다.', placeholder } = {}) {
  if (type === 'empty') return '<footer class="lxp-footer lxp-footer--empty"></footer>';
  if (type === 'button') return `<footer class="lxp-footer lxp-footer--action">${Button({ label: label || '저장하기', block: true })}</footer>`;
  if (type === 'count-button') {
    return `<footer class="lxp-footer lxp-footer--action"><div class="lxp-footer__row">
      <p class="lxp-footer__count">총 <em>${esc(count)}</em>명</p>${Button({ label: label || '대화시작하기' })}
    </div></footer>`;
  }
  if (type === 'message-input') return `<footer class="lxp-footer lxp-footer--chat">${MessageInput({ placeholder })}</footer>`;
  if (type === 'message-block') {
    return `<footer class="lxp-footer lxp-footer--chat lxp-footer--block">
      ${Button({ label: label || '차단 해제', variant: 'gray', size: 'md', icon: 'block', block: true })}
      <p class="lxp-footer__caption">${esc(caption)}</p>
    </footer>`;
  }
  return '';
}

